from collections import deque

def solve_puzzle(grid):
    """
    Try to understand the transformation from demos.
    Input has a symbol forming a boundary, output fills interior with another symbol.
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find the "boundary" symbol (non-zero)
    symbols = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                symbols.add(grid[r][c])

    boundary_val = next(iter(symbols)) if symbols else None

    result = [row[:] for row in grid]

    if boundary_val:
        # Create mask: True for non-zero (boundary cells)
        mask = [[grid[r][c] != 0 for c in range(cols)] for r in range(rows)]

        # Check each zero cell: is it "enclosed" by boundary?
        # Use BFS from edges - any zero reachable from edge is NOT enclosed
        reachable = [[False]*cols for _ in range(rows)]

        # Start from all edge cells that are not boundary
        queue = deque()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                        reachable[r][c] = True
                        queue.append((r, c))

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not reachable[nr][nc] and grid[nr][nc] == 0:
                        reachable[nr][nc] = True
                        queue.append((nr, nc))

        # Cells NOT reachable from edge are enclosed -> fill with 2
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0 and not reachable[r][c]:
                    result[r][c] = 2

    return result

