def solve_puzzle(grid):
    """
    Each row: find the 3s (or boundary symbol), fill between them with 2s.
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find the boundary value
    boundary_val = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                boundary_val = grid[r][c]
                break
        if boundary_val:
            break

    if not boundary_val:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]

    for r in range(rows):
        # Find all positions of boundary value in this row
        positions = []
        for c in range(cols):
            if grid[r][c] == boundary_val:
                positions.append(c)

        if len(positions) >= 2:
            # Fill all cells between the leftmost and rightmost boundary cell
            left = positions[0]
            right = positions[-1]
            for c in range(left + 1, right):
                if grid[r][c] == 0:
                    result[r][c] = 2

    return result

